# filename: examine_json_structure.py
import json

JSON_FILE_PATH = "⟨workdir⟩"

try:
    with open(JSON_FILE_PATH, 'r', encoding='utf-8') as f:
        data = json.load(f)

    print(f"JSON data type: {type(data)}")

    if isinstance(data, list):
        print(f"Number of records in JSON: {len(data)}")
        if len(data) > 0:
            print("\nFirst record structure:")
            first_record = data[0]
            print(json.dumps(first_record, indent=2, ensure_ascii=False))

            print("\nKeys in first record:")
            for key in first_record.keys():
                print(f"  - {key}: {type(first_record[key])}")

    elif isinstance(data, dict):
        print("\nJSON is a dictionary. Keys:")
        for key in data.keys():
            print(f"  - {key}")
            if isinstance(data[key], list) and len(data[key]) > 0:
                print(f"    (list with {len(data[key])} items)")
                if len(data[key]) > 0:
                    print(f"    First item keys: {list(data[key][0].keys())}")

except Exception as e:
    print(f"Error reading JSON file: {e}")
    exit(1)
